    /// # Example
    /// ```rust,no_run
    /// use gpui_px::line;
    /// use std::rc::Rc;
    /// use std::cell::RefCell;
    ///
    /// let hidden = Rc::new(RefCell::new(std::collections::HashSet::new()));
    /// let hidden_clone = hidden.clone();
    ///
    /// let chart = line(&[1.0, 2.0], &[1.0, 2.0])
    ///     .on_legend_click(move |index, _window, _cx| {
